  'After closing, this request cannot receive further deliveries. Record returns against existing receipts and use a new request for replacements or additional deliveries.': 'Después de cerrar, esta solicitud no puede recibir más entregas. Registra devoluciones contra los recibos existentes y usa una nueva solicitud para reemplazos o entregas adicionales.',
