  'Enter minimum pack count and the price per one selling unit. Check price validity and whether tax is included.': 'Ingresa la cantidad mínima de paquetes y el precio por una unidad de venta. Revisa la validez del precio y si el impuesto está incluido.',
  'Enter missing prices or conversion factors in the costing lesson to finish the calculation.': 'Ingresa los precios faltantes o los factores de conversión en la lección de costos para terminar el cálculo.',
  'Enter month-to-date amounts from provider billing. Billing is not automatically synced and spending is not automatically blocked. Leave unknown amounts blank.': 'Ingresa los montos acumulados del mes según la facturación del proveedor. La facturación no se sincroniza automáticamente y el gasto no se bloquea automáticamente. Deja en blanco los montos desconocidos.',
  'Enter non-negative amounts and a positive budget. Use a dot (.) as the decimal separator.': 'Ingresa montos no negativos y un presupuesto positivo. Usa un punto (.) como separador decimal.',
  'Enter purchase quantities': 'Ingresa las cantidades de compra',
  'Enter purchase quantities with up to six decimal places.': 'Ingresa las cantidades de compra con hasta seis decimales.',
  'Enter quantity and unit': 'Ingresa la cantidad y la unidad',
  'Enter required contact and region details, then save privately.': 'Ingresa los datos de contacto y región requeridos, luego guárdalos de forma privada.',
  'Enter required details': 'Ingresa los datos requeridos',
  'Enter servings between 0.001 and 100000.': 'Ingresa porciones entre 0.001 y 100000.',
  'Enter servings for each dish. Ingredients use the selected recipe revisions.': 'Ingresa las porciones para cada platillo. Los ingredientes usan las revisiones de receta seleccionadas.',
  'Enter supplier, buyer and each item’s purchase quantity and unit.': 'Ingresa el proveedor, el comprador y la cantidad de compra y unidad de cada artículo.',
  'Enter the 10-digit business registration number.': 'Ingresa el número de registro comercial de 10 dígitos.',
  'Enter the buyer.': 'Ingresa el comprador.',
  'Enter the email address for the password reset.': 'Ingresa la dirección de correo para restablecer la contraseña.',
  'Enter the exact offer ID configured in Play Console.': 'Ingresa el ID exacto de la oferta configurado en Play Console.',
  'Enter the pack contents using the same unit as the recipe ingredient.': 'Ingresa el contenido del paquete usando la misma unidad que el ingrediente de la receta.',
  'Enter the purchase conversion for this product.': 'Ingresa la conversión de compra para este producto.',
  'Enter the purchase quantity and unit first.': 'Ingresa primero la cantidad y la unidad de compra.',
  'Enter the purchased pack': 'Ingresa el paquete comprado',
  'Enter the quantity actually returned from this receipt. Previous returns and reserved stock limit the available return quantity.': 'Ingresa la cantidad realmente devuelta de esta recepción. Las devoluciones anteriores y el stock reservado limitan la cantidad de devolución disponible.',
  'Enter the quantity to add or subtract, with a reason such as opening count, count discrepancy or waste. On-hand stock cannot fall below reservations.': 'Ingresa la cantidad para agregar o restar, con un motivo como conteo de apertura, diferencia de conteo o desperdicio. El stock disponible no puede bajar de las reservas.',
  'Enter your password again.': 'Ingresa tu contraseña otra vez.',
  'Enter your password.': 'Ingresa tu contraseña.',
  'Enter {0} from {1} to {2}.': 'Ingresa {0} de {1} a {2}.',
  'Entered-price subtotal': 'Subtotal con precio ingresado',
  'Estimated': 'Estimado',
  'Estimated profit': 'Ganancia estimada',
  'Estimated profit = revenue minus recorded cost. Unentered expenses and taxes are excluded. Weeks run Monday through Sunday.': 'La ganancia estimada = ingresos menos el costo registrado. Los gastos e impuestos no ingresados se excluyen. Las semanas van de lunes a domingo.',
  'Estimated profit subtracts recorded costs from recorded revenue. It is not accounting net profit or an automatic POS feed. Review missing sales and costs yourself.': 'La ganancia estimada resta los costos registrados de los ingresos registrados. No es la ganancia neta contable ni un flujo automático del POS. Revisa tú mismo las ventas y los costos faltantes.',
  'Estimated profit uses recorded costs. Unentered expenses and taxes are excluded.': 'La ganancia estimada usa los costos registrados. Los gastos e impuestos no ingresados se excluyen.',
  'Estimated total': 'Total estimado',
  'Estimated total including shipping': 'Total estimado con envío',
  'Every past request is rewritten at the new price.': 'Cada solicitud pasada se reescribe al nuevo precio.',
  'Everyday cooks': 'Cocineros de todos los días',
  'Everything you need, nothing missed.': 'Todo lo que necesitas, nada que se te pase.',
  'Example result': 'Resultado de ejemplo',
  'Example result: visible to signed-in free and paid members. No real listing was published.': 'Resultado de ejemplo: visible para miembros gratis y de pago que han iniciado sesión. No se publicó ningún anuncio real.',
  'Example tried. Complete the lesson below or keep experimenting.': 'Ejemplo probado. Completa la lección de abajo o sigue experimentando.',
  'Example: 1 pack = 400 g → enter 400. Until supplied, cost remains incomplete. Changing either unit clears this conversion.': 'Ejemplo: 1 paquete = 400 g → ingresa 400. Hasta que se proporcione, el costo sigue incompleto. Cambiar cualquiera de las unidades borra esta conversión.',
  'Example: 10 kg per box → selling unit box, content 10, content unit kg': 'Ejemplo: 10 kg por caja → unidad de venta caja, contenido 10, unidad de contenido kg',
  'Example: 2 packs of tofu, 1 bottle of sesame oil, 10 eggs': 'Ejemplo: 2 paquetes de tofu, 1 botella de aceite de ajonjolí, 10 huevos',
