  'Example: Kimchi stew': 'Ejemplo: Guiso de kimchi',
  'Example: for a 300 g pack, enter 300. This helps calculate packs next time.': 'Ejemplo: para un paquete de 300 g, ingresa 300. Esto ayuda a calcular paquetes la próxima vez.',
  'Example: pork, kimchi, tofu, green onion': 'Ejemplo: cerdo, kimchi, tofu, cebolla larga',
