  'Filter the ledger by date, status and supplier, then export PDF/CSV. When copying a request, recheck current prices, quantities and delivery date.': 'Filtra el registro por fecha, estado y proveedor, luego exporta PDF/CSV. Al copiar una solicitud, vuelve a revisar los precios, las cantidades y la fecha de entrega actuales.',
