  'First create an AI draft from the video title and description. If details are missing, paste YouTube captions and': 'Primero crea un borrador de IA a partir del título y la descripción del video. Si faltan detalles, pega los subtítulos de YouTube y',
  'First create an AI draft from the video title and description. If details are missing, paste YouTube captions and add a dish name or key ingredient hints.': 'Primero crea un borrador de IA a partir del título y la descripción del video. Si faltan detalles, pega los subtítulos de YouTube y agrega un nombre del platillo o pistas de ingredientes clave.',
