  'Follow up & receive': 'Seguimiento y recepción',
  'Follow video tutorials or read detailed guides on our blog. Content is in Korean.': 'Sigue los tutoriales en video o lee guías detalladas en nuestro blog. El contenido está en coreano.',
  'Food suppliers': 'Proveedores de alimentos',
  'For 500g × 2 bags, enter content 500, unit g and inner pack count 2. Verify the actual sale option.': 'Para 500 g × 2 bolsas, ingresa contenido 500, unidad g y cantidad de paquete interno 2. Verifica la opción de venta real.',
  'For 800 g of edible ingredient at 80% yield, purchase needs are 1,000 g. Usage quantity means the amount after trimming.': 'Para 800 g de ingrediente comestible con un rendimiento del 80 %, la necesidad de compra es 1,000 g. La cantidad de uso significa la cantidad después de recortar.',
  'For a five-kilogram box, set selling unit to box, content amount to five and content unit to kg.': 'Para una caja de cinco kilos, configura la unidad de venta como caja, la cantidad de contenido como cinco y la unidad de contenido como kg.',
