  'If the business is published, customers will see this product again. Check its specification and price.': 'Si el negocio está publicado, los clientes verán este producto otra vez. Revisa su especificación y precio.',
  'If the initial result is incomplete, follow the steps below and recreate it with captions.': 'Si el resultado inicial está incompleto, sigue los pasos abajo y vuélvelo a crear con subtítulos.',
  'If the supplier, product, specification or amount differs, edit and reapprove the request. Check final options and shipping at Coupang.': 'Si el proveedor, el producto, la especificación o el importe difieren, edita y vuelve a aprobar la solicitud. Revisa las opciones finales y el envío en Coupang.',
  'If this differs from the approval, edit and reapprove the request first. Check final options, price and shipping at Coupang.': 'Si esto difiere de la aprobación, primero edita y vuelve a aprobar la solicitud. Revisa las opciones finales, el precio y el envío en Coupang.',
