  'Only ingredient names are sent. Up to 20 items per request, using your existing AI allowance. Suggestions are editable.': 'Solo se envían nombres de ingredientes. Hasta 20 elementos por solicitud, usando tu asignación de IA existente. Las sugerencias se pueden editar.',
