  'The save result is uncertain. Retrying the same content will not create a duplicate.': 'El resultado de guardado es incierto. Reintentar el mismo contenido no creará un duplicado.',
  'The saved request was removed. Review it again.': 'La solicitud guardada fue eliminada. Revísala otra vez.',
  'The selected YouTube video information is invalid. Please select the video again.': 'La información del video de YouTube seleccionado no es válida. Vuelve a seleccionar el video.',
  'The selected cost and price are recorded at save time. Later price changes do not alter past sales.': 'El costo y el precio seleccionados se registran al momento de guardar. Los cambios posteriores de precio no alteran las ventas pasadas.',
  'The selected product is not visible. Check publication, placement permission for this platform, review expiry and ingredient names.': 'El producto seleccionado no es visible. Revisa la publicación, el permiso de ubicación para esta plataforma, el vencimiento de la revisión y los nombres de los ingredientes.',
  'The server could not process your shopping request. Try again or contact support.': 'El servidor no pudo procesar tu solicitud de compras. Inténtalo de nuevo o contacta al soporte.',
  'The server needs an update for shared business work. Personal tools are still available.': 'El servidor necesita una actualización para el trabajo compartido del negocio. Las herramientas personales siguen disponibles.',
  'The shopping list was updated. Please review it again.': 'La lista de compras se actualizó. Revísala otra vez.',
  'The store did not open. Try again or copy the link into your browser.': 'La tienda no se abrió. Inténtalo de nuevo o copia el enlace en tu navegador.',
  'The supplier or product changed, or its unit does not match. Check availability, content quantity and pack unit, then select it again.': 'El proveedor o el producto cambió, o su unidad no coincide. Revisa la disponibilidad, la cantidad de contenido y la unidad del paquete, y luego selecciónalo otra vez.',
  'The supplier will be unpublished if no publishable products remain.': 'El proveedor dejará de publicarse si no quedan productos publicables.',
  'The three most recent cleanups can each be restored for 30 minutes.': 'Las tres limpiezas más recientes se pueden restaurar por 30 minutos cada una.',
  'The workspace limit was reached. Review existing records or invitations.': 'Se alcanzó el límite del espacio de trabajo. Revisa los registros o invitaciones existentes.',
  'There are no captions on the clipboard.': 'No hay subtítulos en el portapapeles.',
  'There are no cooking steps to guide.': 'No hay pasos de cocción para guiar.',
  'There are no draft attempts to measure yet.': 'Aún no hay intentos de borrador para medir.',
  'There are no meals to copy.': 'No hay comidas para copiar.',
  'There are no recent errors to clear.': 'No hay errores recientes para borrar.',
  'There are no wording edits to apply. Review the checks and continue with the original.': 'No hay ediciones de texto para aplicar. Revisa las comprobaciones y continúa con el original.',
  'There is no kitchen data to organize.': 'No hay datos de cocina para organizar.',
  'There is no kitchen data to restore.': 'No hay datos de cocina para restaurar.',
  'There is no recent kitchen cleanup to undo.': 'No hay ninguna limpieza reciente de cocina para deshacer.',
  'These are catalog estimates at comparison time. Editing quantities, prices or suppliers changes the estimate.': 'Estas son estimaciones de catálogo al momento de la comparación. Editar cantidades, precios o proveedores cambia la estimación.',
  'These are scaled cooking quantities. Set shopping purchase quantities separately.': 'Estas son cantidades de cocción ajustadas. Configura por separado las cantidades de compra para la lista de compras.',
  'These are the selections when the draft was created. Check the current request above for subsequent edits.': 'Estas son las selecciones cuando se creó el borrador. Revisa la solicitud actual arriba para ver las ediciones posteriores.',
  'These units differ. Enter your conversion for costing.': 'Estas unidades difieren. Ingresa tu conversión para el costo.',
  'These views use the current account’s records. Choosing a work view does not change access permissions.': 'Estas vistas usan los registros de la cuenta actual. Elegir una vista de trabajo no cambia los permisos de acceso.',
  'This AI draft was created only from the selected YouTube video.': 'Este borrador con IA se creó solo a partir del video de YouTube seleccionado.',
  'This AI draft was created only from the selected YouTube video. Review, edit, and save it.': 'Este borrador con IA se creó solo a partir del video de YouTube seleccionado. Revísalo, edítalo y guárdalo.',
  'This YouTube link cannot be opened.': 'No se puede abrir este enlace de YouTube.',
  'This account has no access. Check your permissions with the owner.': 'Esta cuenta no tiene acceso. Revisa tus permisos con el propietario.',
  'This accounts for trimming loss in costing. It does not change shopping or inventory quantities.': 'Esto considera la merma por recorte en el costo. No cambia las cantidades de compras ni de inventario.',
  'This affiliate link already exists. Check existing offers or trash.': 'Este enlace de afiliado ya existe. Revisa las ofertas existentes o la papelera.',
  'This affiliate link is already registered. Review the existing product below.': 'Este enlace de afiliado ya está registrado. Revisa el producto existente abajo.',
  'This area is for administrators.': 'Esta área es para administradores.',
  'This budget is for alerts. It does not change server capacity or billing.': 'Este presupuesto es para alertas. No cambia la capacidad del servidor ni la facturación.',
  'This checks configuration only. Successful purchases and notifications still require live verification.': 'Esto solo verifica la configuración. Las compras y notificaciones exitosas aún requieren verificación en vivo.',
  'This difference excludes no unentered costs and is not accounting net profit.': 'Esta diferencia no excluye costos no ingresados y no es la utilidad neta contable.',
  'This example previews the document structure. Use your own data for real PDF preview, export and printing.': 'Este ejemplo muestra una vista previa de la estructura del documento. Usa tus propios datos para una vista previa real de PDF, exportación e impresión.',
  'This exceeds the outstanding quantity. Review current receipts and returns.': 'Esto excede la cantidad pendiente. Revisa los recibos y devoluciones actuales.',
  'This exceeds the quantity still returnable from this receipt.': 'Esto excede la cantidad que aún se puede devolver de esta recepción.',
  'This field is required.': 'Este campo es obligatorio.',
  'This invitation expired or belongs to another email. Sign in with the invited address and verify your email.': 'Esta invitación expiró o pertenece a otro correo electrónico. Inicia sesión con la dirección invitada y verifica tu correo electrónico.',
  'This is a Coupang Partners affiliate link. We receive a commission from qualifying purchases. Check final prices and shipping on Coupang.': 'Este es un enlace de afiliado de Coupang Partners. Recibimos una comisión por las compras que califiquen. Revisa los precios finales y el envío en Coupang.',
  'This is a draft recipe based on a YouTube video.': 'Este es un borrador de receta basado en un video de YouTube.',
  'This is a marketplace. Check the actual seller on the product page, then select or register that seller below.': 'Este es un marketplace. Revisa el vendedor real en la página del producto y luego selecciona o registra ese vendedor abajo.',
