  'Use AI as a drafting tool for menu development.': 'Usa la IA como herramienta de borrador para desarrollar el menú.',
  'Use Back after practicing to return to this lesson.': 'Usa Atrás después de practicar para volver a esta lección.',
  'Use Coupang search to check other product sizes. General search is not an affiliate link and does not import products automatically.': 'Usa la búsqueda de Coupang para revisar otros tamaños de producto. La búsqueda general no es un enlace de afiliado y no importa productos automáticamente.',
  'Use Find suppliers to search by product, category and delivery region, and review your listing.': 'Usa Buscar proveedores para buscar por producto, categoría y región de entrega, y revisa tu listado.',
  'Use Purchase quantity and unit to enter what you will buy. Cooking may use 200 mL of milk while you buy one carton. The original cooking ingredient stays unchanged.': 'Usa Cantidad de compra y unidad para ingresar lo que vas a comprar. Al cocinar puedes usar 200 mL de leche mientras compras un cartón. El ingrediente original de la receta permanece sin cambios.',
  'Use Quick price edit for pack quantity, purchase unit and pack price. For 1 kg costing KRW 12,000, enter 1, kg and 12,000.': 'Usa Edición rápida de precio para la cantidad del empaque, la unidad de compra y el precio del empaque. Para 1 kg que cuesta KRW 12,000, ingresa 1, kg y 12,000.',
  'Use Shopping prep in recipe details. Check what you already have and what is actually missing.': 'Usa Preparación de compras en los detalles de la receta. Revisa lo que ya tienes y lo que realmente falta.',
  'Use a business contact that you intend to make public. You do not need real contact details for the training example.': 'Usa un contacto comercial que piensas hacer público. No necesitas datos de contacto reales para el ejemplo de entrenamiento.',
  'Use a development revision for candidates; an approved revision for launch.': 'Usa una versión de desarrollo para los candidatos; una versión aprobada para el lanzamiento.',
  'Use a password different from your current one.': 'Usa una contraseña diferente a la actual.',
  'Use a recognizable name and note baseline servings in the summary. Distinguish source details from your own changes.': 'Usa un nombre reconocible y anota las porciones base en el resumen. Distingue los datos de origen de tus propios cambios.',
  'Use a searchable product name': 'Usa un nombre de producto que se pueda buscar',
